import React, { useState, useEffect, useCallback } from 'react';

// Helper component for the card structure
const StatusCard = () => {
  const [statusMessage, setStatusMessage] = useState('Awaiting initial check...');
  const [isLoading, setIsLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Function to fetch status from backend
  const fetchStatus = useCallback(async () => {
    setIsLoading(true);
    setStatusMessage('Fetching status from backend...');
    try {
      // Note: Assuming backend runs on 3000 as per requirement
      const response = await fetch('http://localhost:3000/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      // Assuming the backend returns a simple status message or object
      setStatusMessage(data.message || '✅ System is Live & Connected.');
    } catch (error) {
      console.error("Error fetching status:", error);
      setStatusMessage(`❌ Connection Error: Could not reach backend. (${error.message})`);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Initial fetch on mount
  useEffect(() => {
    fetchStatus();
  }, [fetchStatus]);

  // Handler for the refresh button
  const handleRefresh = () => {
    fetchStatus();
  };

  // CRITICAL UNBREAKABLE CODE RULE 1: Must render a launcher button if visibility is toggled
  // Since this component manages its own state and the requirement implies a visible card,
  // we ensure the primary action (refresh) is visible, and if we were to implement a modal,
  // the launcher button would be present.

  return (
    <div style={styles.cardContainer}>
      <div style={styles.cardContent}>
        <div style={styles.header}>
          <span style={styles.icon}>🟢</span>
          <h3 style={styles.title}>System Status</h3>
        </div>

        <div style={styles.badge}>
          {isLoading ? '⏳ Checking...' : '🟢 Live & Connected'}
        </div>

        <p style={styles.message}>{statusMessage}</p>

        <button 
          onClick={handleRefresh} 
          disabled={isLoading} 
          style={styles.refreshButton}
        >
          {isLoading ? 'Refreshing...' : '🔄 Refresh Status'}
        </button>
      </div>

      {/* Modal implementation placeholder to satisfy Rule 1 if toggled */}
      {isModalOpen && (
        <div style={styles.modalOverlay}>
          <div style={styles.modalContent}>
            <h4>Detailed Status Report</h4>
            <p>This is detailed information about the system state.</p>
            <button onClick={() => setIsModalOpen(false)} style={styles.closeButton}>Close</button>
          </div>
        </div>
      )}

      {/* Launcher button required if modal state is managed, even if not explicitly triggered by UI flow here */}
      {!isModalOpen && (
        <button onClick={() => setIsModalOpen(true)} style={styles.launcherButton}>
          🚀 Launch Detailed View
        </button>
      )}
    </div>
  );
};

